import 'package:flutter/material.dart'; import 'package:video_player/video_player.dart'; import '../../repositories/video_repository.dart'; import '../../services/api_client.dart'; import '../../models/video.dart';
class VideoScreen extends StatefulWidget { const VideoScreen({super.key, required this.videoId}); final String videoId; @override State<VideoScreen> createState() => _VideoScreenState(); }
class _VideoScreenState extends State<VideoScreen> { final repo = VideoRepository(ApiClient()); Video? video; VideoPlayerController? player; @override void initState() { super.initState(); _load(); } Future<void> _load() async { final v = await repo.details(widget.videoId); final p = VideoPlayerController.networkUrl(Uri.parse(v.hlsUrl!)); await p.initialize(); p.addListener(() { if (p.value.position.inSeconds % 15 == 0) repo.saveProgress(v.id, p.value.position, p.value.duration); }); setState(() { video = v; player = p; }); } @override void dispose() { player?.dispose(); super.dispose(); } @override Widget build(BuildContext c) { final p = player; return Scaffold(appBar: AppBar(title: Text(video?.title ?? 'Video')), body: p == null ? const Center(child: CircularProgressIndicator()) : Column(children: [AspectRatio(aspectRatio: p.value.aspectRatio, child: VideoPlayer(p)), VideoProgressIndicator(p, allowScrubbing: true), IconButton(icon: Icon(p.value.isPlaying ? Icons.pause : Icons.play_arrow), onPressed: () => setState(() => p.value.isPlaying ? p.pause() : p.play()))])); } }
